"use client";

import React, { useRef } from 'react';
import { motion, useScroll, useTransform} from "framer-motion";
import { cn } from "@/lib/utils";
import { usePrefersReducedMotion } from "./use-animation-hooks";

interface ScrollRevealProps {
  text: string;
  className?: string;
  wordClassName?: string;
  splitBy?: 'words' | 'letters';
}

interface RevealTokenProps {
  token: string;
  index: number;
  total: number;
  scrollYProgress: ReturnType<typeof useScroll>['scrollYProgress'];
  splitBy: 'words' | 'letters';
  wordClassName?: string;
  prefersReducedMotion: boolean;
}

const RevealToken: React.FC<RevealTokenProps> = ({
  token,
  index,
  total,
  scrollYProgress,
  splitBy,
  wordClassName,
  prefersReducedMotion,
}) => {
  const start = index / total;
  const end = (index + 1) / total;

  const opacity = useTransform(scrollYProgress, [start, end], [0.15, 1]);
  const y = useTransform(scrollYProgress, [start, end], [8, 0]);
  const scale = useTransform(scrollYProgress, [start, end], [0.98, 1]);

  const isSpace = token === ' ';

  if (prefersReducedMotion) {
    return (
      <span
        key={index}
        className={cn(
          'inline-block origin-bottom-left',
          splitBy === 'words' ? 'mr-[0.25em]' : '',
          isSpace ? 'w-[0.25em]' : '',
          wordClassName
        )}
      >
        {isSpace ? '\u00A0' : token}
      </span>
    );
  }

  return (
    <motion.span
      key={index}
      style={{ opacity, y, scale }}
      className={cn(
        'inline-block origin-bottom-left',
        splitBy === 'words' ? 'mr-[0.25em]' : '',
        isSpace ? 'w-[0.25em]' : '',
        wordClassName
      )}
    >
      {isSpace ? '\u00A0' : token}
    </motion.span>
  );
};

export const ScrollReveal: React.FC<ScrollRevealProps> = ({
  text,
  className,
  wordClassName,
  splitBy = 'words',
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const prefersReducedMotion = usePrefersReducedMotion();

  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ['start 85%', 'end 35%'],
  });

  const tokens = splitBy === 'words' ? text.split(' ') : text.split('');

  return (
    <div ref={containerRef} className={cn('relative py-6', className)}>
      <p className="flex flex-wrap font-bold leading-normal">
        {tokens.map((token, i) => (
          <RevealToken
            key={i}
            token={token}
            index={i}
            total={tokens.length}
            scrollYProgress={scrollYProgress}
            splitBy={splitBy}
            wordClassName={wordClassName}
            prefersReducedMotion={prefersReducedMotion}
          />
        ))}
      </p>
    </div>
  );
};

import { useEffect, useRef, useState } from 'react';
import type { RefObject } from 'react';

export const usePrefersReducedMotion = (): boolean => {
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);

  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(mediaQuery.matches);

    const listener = (event: MediaQueryListEvent) => {
      setPrefersReducedMotion(event.matches);
    };

    mediaQuery.addEventListener('change', listener);
    return () => {
      mediaQuery.removeEventListener('change', listener);
    };
  }, []);

  return prefersReducedMotion;
};

export const useAnimateOnScroll = (options?: IntersectionObserverInit) => {
  const [ref, setRef] = useState<HTMLElement | null>(null);
  const [isIntersecting, setIsIntersecting] = useState(false);

  useEffect(() => {
    if (!ref) return;

    const observer = new IntersectionObserver(([entry]) => {
      if (entry) {
        setIsIntersecting(entry.isIntersecting);
      }
    }, options);

    observer.observe(ref);
    return () => {
      observer.unobserve(ref);
    };
  }, [ref, options]);

  return [setRef, isIntersecting] as const;
};

export function useInView<T extends Element = HTMLDivElement>(
  options: IntersectionObserverInit = { rootMargin: '100px 0px', threshold: 0 },
): [RefObject<T | null>, boolean] {
  const ref = useRef<T | null>(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof window === 'undefined' || !('IntersectionObserver' in window)) {
      setInView(true);
      return;
    }
    const io = new IntersectionObserver(([entry]) => setInView(entry.isIntersecting), options);
    io.observe(el);
    return () => io.disconnect();
  }, [options]);
  return [ref, inView];
}

export function useShouldAnimate<T extends Element = HTMLDivElement>(): [RefObject<T | null>, boolean] {
  const reduced = usePrefersReducedMotion();
  const [ref, inView] = useInView<T>();
  return [ref, inView && !reduced];
}
